entries[144239] = { ["name"] = "The Emperor's Capacitor", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nChest Leather\n8 Armor\n+5 [Agility or Intellect]\n+7 Stamina\n+ 6 Critical Strike\n+ 4 Mastery\nDurability 200 / 200\nClasses: Monk\nEquip: Chi spenders increase the damage of your next Crackling Jade Lightning by 100% and reduce its cost by 5%, stacking up to 20 times.\n\"Stolen from the Highkeeper Ra-den, the Fallen Keeper of Storms.\"\nSell Price:" }
entries[144240] = { ["name"] = "Ravaged Supplies", ["text"] = "Quest Item\n\"Covered in just a bit of fel goop. It's probably fine.\"" }
