entries[144242] = { ["name"] = "X'oni's Caress", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nHands Leather\n5 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 4 Haste\n+ 3 Mastery\nDurability 70 / 70\nClasses: Druid\nEquip: Ironbark has 20% reduced cooldown and allies protected by your Ironbark also receive 75% of the healing from each of your active Rejuvenations.\n\"X'oni's mere presence was enough to cheer up her allies. Even though she was one of the most powerful druids to ever exist, many of her tricks were learned from the legendary priest, Phyrix.\"\nSell Price:" }
entries[144243] = { ["name"] = "Arsenal: Malevolent Gladiator's Weapons", ["text"] = "Binds when picked up\nUse: Collect the appearances of the Malevolent Gladiator's weapons set." }
entries[144244] = { ["name"] = "Kam Xi'raff", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nHead Cloth\n4 Armor\n+5 Intellect\n+7 Stamina\n+ 4 Critical Strike\n+ 6 Haste\nDurability 120 / 120\nClasses: Priest\nEquip: Reduces the cost of your healing spells by 3%.\nEquip: Using Light's Wrath reduces the mana cost of your spells by 50% for 1 sec, increased by 1 sec per ally affected by your Atonement.\n\"Named after a unique priest, whose name no one could utter.\"\nSell Price:" }
