entries[144258] = { ["name"] = "Velen's Future Sight", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+5 [Agility or Strength or Intellect]\n+ 2 Critical Strike\n+ 2 Haste\n+ 2 Mastery\nUse: Increase all healing done by 15% and causes 50% of overhealing on players to be redistributed to up to 3 nearby injured allies, for 10 sec. (1 Min, 15 Sec Cooldown)\n\"Velen the Ageless One, known by his people as the Prophet, blessed with the gift of Sight, and aided by the Light, has led the draenei for over 25,000 years.\"\nSell Price:" }
entries[144259] = { ["name"] = "Kil'jaeden's Burning Wish", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+5 [Agility or Strength or Intellect]\n+ 2 Critical Strike\n+ 2 Haste\n+ 2 Mastery\nUse: Launch a vortex of destruction that seeks your current enemy. When it reaches the target, it explodes, dealing a critical strike to all enemies within 10 yds for ( 32 * 200 / 100) Fire damage. (1 Min, 15 Sec Cooldown)\n\"Kil'jaeden the Deceiver, supreme commander of the Burning Legion, has a simple agenda: consume all life and magic, assimilate every race into the Legion's ranks, slay any who dare resist, and destroy all of creation.\"\nSell Price:" }
entries[144260] = { ["name"] = "Ice Time", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nShoulder Cloth\n3 Armor\n+4 Intellect\n+6 Stamina\n+ 5 Critical Strike\n+ 3 Haste\nDurability 120 / 120\nClasses: Mage\nEquip: Your Frozen Orb explodes into a Frost Nova that deals (150% of Spell Power) damage.\n\"They always seem to have something magical up their sleeves.\"\nSell Price:" }
